(4693901, 675994, 93319, '<td valign="top">I love the color.  Nice mix and just enough space.</td>', 'I love the color.  Nice mix and just enough space.', '2008-05-10 12:23:45.000000', NULL, 1),
(4694076, 676127, 5746, '<td valign="top">Great idea, well conveyed. One of the most creative stories.</td>', 'Great idea, well conveyed. One of the most creative stories.', '2008-05-10 16:49:35.000000', NULL, 1),
(4694093, 676101, 5746, '<td valign="top">ROTFL :))) It''s not only great composition, but also extremly funny title (and story behaind). Their expressions are just right for the story :)) 10.</td>', 'ROTFL :))) It''s not only great composition, but also extremly funny title (and story behaind). Their expressions are just right for the story :)) 10.', '2008-05-10 17:05:57.000000', NULL, 1),
