(4801258, 675638, 67697, '<td valign="top">Don''t know why it scored the way it did.  I gave it a 7.  My fave part was the lighting.  Maybe the setup in the background took away from the supposed outdoor scene?</td>', 'Don''t know why it scored the way it did.  I gave it a 7.  My fave part was the lighting.  Maybe the setup in the background took away from the supposed outdoor scene?', '2008-07-03 16:22:46.000000', NULL, 0),
(4806771, 676195, 43463, '<td valign="top">Love the processing - makes the photo really pop. Great lighting, great focus, and nice composition. It really captures the feel of being there (minus the smell I am sure:-) ) of standing there at the fish market. I like this photo for it captures a moment and feel of a slice of ''culture'' that has largely disappeared due to large supermarket chains.</td>', 'Love the processing - makes the photo really pop. Great lighting, great focus, and nice composition. It really captures the feel of being there (minus the smell I am sure:-) ) of standing there at the fish market. I like this photo for it captures a moment and feel of a slice of ''culture'' that has largely disappeared due to large supermarket chains.', '2008-07-06 11:01:37.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4806865, 676195, 30982, '<td valign="top">What a fun and delightful shot!  How did you process this?</td>', 'What a fun and delightful shot!  How did you process this?', '2008-07-06 12:24:40.000000', NULL, 0),
(4831792, 676195, 25355, '<td valign="top">I think it''s a great composition; it tells a story well. No need to get in any closer, really. ;-)</td>', 'I think it''s a great composition; it tells a story well. No need to get in any closer, really. ;-)', '2008-07-17 23:30:49.000000', NULL, 0),
(4888977, 676038, 67258, '<td valign="top">A strong sense of narrative - I am really glad you weren''t tempted to crop/frame in closer, as the entire scene makes for the story.  Very nicely observed.</td>', 'A strong sense of narrative - I am really glad you weren''t tempted to crop/frame in closer, as the entire scene makes for the story.  Very nicely observed.', '2008-08-14 17:15:30.000000', NULL, 0),
(4910087, 675222, 3214, '<td valign="top">I thought this was really under-rated.  Tells a great story!</td>', 'I thought this was really under-rated.  Tells a great story!', '2008-08-25 16:30:40.000000', NULL, 0),
(4921812, 676108, 68586, '<td valign="top">What a sweetie  :- )</td>', 'What a sweetie  :- )', '2008-08-30 16:58:57.000000', NULL, 0),
(4922544, 675401, 42495, '<td valign="top">Not long ago my 4 yr old daughter said to me, "When I die I want to come back as a boy so I can go to work with you."  If she knew what I did in real life she wouldn''t say that.  This reminds me of that special moment and makes me want to be a better photographer.  Well done.</td>', 'Not long ago my 4 yr old daughter said to me, "When I die I want to come back as a boy so I can go to work with you."  If she knew what I did in real life she wouldn''t say that.  This reminds me of that special moment and makes me want to be a better photographer.  Well done.', '2008-08-31 01:34:41.000000', NULL, 0),
(4936984, 676185, 67145, '<td valign="top">brilliant shot .. it definitely tells a story .. <br/>i read your photographer''s comments .. i feel very lucky to live in australia because we have more freedom to take pics ..!!!.<br/>BUT .. at our local mall which has some great things to photograph with perspective, ppl and heaps of interesting angles and shapes .. well i''ve been told to put my camera away several times .. i have to be sneaky .. but i only get a warning .. which isnt too scarey and they''re usually pretty nice about it  .. :)<br/>it would be quite a culture shock going from springfield, virginia to Senegal ... i cant imagine the amazing photographic opportunities you''ll get on your travels .. <br/>thankyou so much for all your comments .. :)</td>', 'brilliant shot .. it definitely tells a story .. i read your photographer''s comments .. i feel very lucky to live in australia because we have more freedom to take pics ..!!!.BUT .. at our local mall which has some great things to photograph with perspective, ppl and heaps of interesting angles and shapes .. well i''ve been told to put my camera away several times .. i have to be sneaky .. but i only get a warning .. which isnt too scarey and they''re usually pretty nice about it  .. :)it would be quite a culture shock going from springfield, virginia to Senegal ... i cant imagine the amazing photographic opportunities you''ll get on your travels .. thankyou so much for all your comments .. :)', '2008-09-05 19:38:18.000000', NULL, 0),
(4956392, 676161, 97893, '<td valign="top">Beautiful picture! Love it!</td>', 'Beautiful picture! Love it!', '2008-09-15 14:24:06.000000', NULL, 0),
