(5142051, 675401, 100301, '<td valign="top">just brilliant.</td>', 'just brilliant.', '2008-12-20 00:02:07.000000', NULL, 0),
(5161309, 674352, 61651, '<td valign="top">Clever use of Hemingway''s brag - the sadness of the story hits immediately, made keener by all those cheery colors and designs.</td>', 'Clever use of Hemingway''s brag - the sadness of the story hits immediately, made keener by all those cheery colors and designs.', '2008-12-31 22:08:53.000000', NULL, 0),
(5204905, 675801, 30982, '<td valign="top">Heh - I''ve no gripes with the lighting at all.  It''s what makes the shot.  Bah on the naysayers, says me.</td>', 'Heh - I''ve no gripes with the lighting at all.  It''s what makes the shot.  Bah on the naysayers, says me.', '2009-01-19 17:48:25.000000', NULL, 0),
(5271296, 676165, 51538, '<td valign="top">As a result of seeing your Post-It entry, I came to look at your portfolio.  You have a nice collection of photos herein.  This one especially caught my eye.  What a wonderful, long story.  Nice work indeed.</td>', 'As a result of seeing your Post-It entry, I came to look at your portfolio.  You have a nice collection of photos herein.  This one especially caught my eye.  What a wonderful, long story.  Nice work indeed.', '2009-02-23 19:55:04.000000', NULL, 0),
(5284497, 675401, 98771, '<td valign="top">I stumbled on to this image, quite by accident. I have to say I''m very glad I did, this is wonderful. The story behind it is touching, being a father myself it is a hard task to always be what they believe us to be. Although a bit late, very well done.<br/> <br/>Mac,</td>', 'I stumbled on to this image, quite by accident. I have to say I''m very glad I did, this is wonderful. The story behind it is touching, being a father myself it is a hard task to always be what they believe us to be. Although a bit late, very well done. Mac,', '2009-03-02 18:24:16.000000', NULL, 0),
(5405895, 675801, 4793, '<td valign="top">Nice shot</td>', 'Nice shot', '2009-03-28 22:30:01.000000', NULL, 0),
